<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {AlertCircle,Building2,ChevronLeft,ChevronRight,KeyRound,LoaderCircle,Pencil,Plus,RefreshCw,Search,UsersRound,X} from 'lucide-vue-next';
import {createRequestGuard} from '../lib/async-response';
type Item=Record<string,any>;
const props=defineProps<{currentUser:Item;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{updated:[];notice:[message:string]}>();
const rows=ref<Item[]>([]);const loading=ref(true);const error=ref('');const search=ref('');const status=ref('all');const page=ref(1);const lastPage=ref(1);const total=ref(0);const dialogOpen=ref(false);const dialog=ref<HTMLElement|null>(null);const selected=ref<Item|null>(null);const saving=ref(false);const formError=ref('');const resetPassword=ref(false);const form=ref({name:'',email:'',role:'editor',active:true,password:'',password_confirmation:''});const reads=createRequestGuard();const writes=createRequestGuard();let debounce:ReturnType<typeof setTimeout>|undefined;let returnFocus:HTMLElement|null=null;
const suiteAccount=computed(()=>selected.value?.auth_provider==='suite');
const ownAccount=computed(()=>selected.value?.id===props.currentUser.id);
function role(value:string){return ({owner:'Administrador principal',admin:'Administrador',editor:'Autor',viewer:'Leitura'} as Record<string,string>)[value]??value;}
function date(value:string|null){return value?new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Ainda não acessou';}
async function load(){const current=reads.next();loading.value=true;error.value='';try{const result=await props.request('/users?'+new URLSearchParams({search:search.value,status:status.value,page:String(page.value)}));if(!current())return;rows.value=result.users;lastPage.value=result.last_page;total.value=result.total;}catch(e){if(current())error.value=(e as Error).message;}finally{if(current())loading.value=false;}}
async function open(user:Item|null=null){selected.value=user;form.value={name:user?.name??'',email:user?.email??'',role:user?.role??'editor',active:user?.active??true,password:'',password_confirmation:''};resetPassword.value=false;formError.value='';returnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;dialogOpen.value=true;await nextTick();dialog.value?.querySelector<HTMLInputElement>('input:not([disabled])')?.focus();}
function close(){if(saving.value)return;writes.invalidate();dialogOpen.value=false;form.value.password='';form.value.password_confirmation='';returnFocus?.focus();returnFocus=null;}
async function save(){if(saving.value)return;const current=writes.next();saving.value=true;formError.value='';try{const input:Item={name:form.value.name.trim(),email:form.value.email.trim(),role:form.value.role};if(selected.value){input.active=form.value.active;input.version=selected.value.version;}if(!selected.value||resetPassword.value){input.password=form.value.password;input.password_confirmation=form.value.password_confirmation;}const result=await props.request(selected.value?'/users/'+selected.value.id:'/users',selected.value?'PATCH':'POST',input);if(!current())return;dialogOpen.value=false;emit('notice',result.message);emit('updated');await load();}catch(e){if(current())formError.value=(e as Error).message;}finally{form.value.password='';form.value.password_confirmation='';if(current())saving.value=false;}}
function changePage(value:number){page.value=value;load();}
function keydown(event:KeyboardEvent){if(!dialogOpen.value)return;if(event.key==='Escape'){close();return;}if(event.key!=='Tab'||!dialog.value)return;const elements=[...dialog.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(el=>el.getClientRects().length);const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
watch([search,status],()=>{page.value=1;if(debounce)clearTimeout(debounce);debounce=setTimeout(load,250);});
onMounted(()=>{load();window.addEventListener('keydown',keydown);});
onUnmounted(()=>{reads.invalidate();writes.invalidate();if(debounce)clearTimeout(debounce);window.removeEventListener('keydown',keydown);form.value.password='';form.value.password_confirmation='';});
</script>
<template>
 <div class="content-view users-management"><div class="page-heading"><div><div class="section-eyebrow">ACESSOS DISPONIBILIZADOS PELA INOVADORA</div><h1>Usuários e acessos</h1><p>Cadastre quem pode entrar e acompanhe os acessos da sua instalação.</p></div><button class="primary-button" @click="open()"><Plus :size="17"/>Cadastrar usuário</button></div><div class="users-suite-note"><Building2 :size="23"/><div><strong>Colaboradores entram com a Suíte</strong><p>O cadastro local é criado após o primeiro login validado na Suíte, com perfil de administrador. Para as demais pessoas, use Cadastrar usuário.</p></div></div>
  <div class="users-toolbar"><div class="input-with-icon"><Search :size="16"/><input v-model="search" aria-label="Buscar usuários" placeholder="Buscar por nome ou e-mail…"></div><select v-model="status" aria-label="Situação do acesso"><option value="all">Todos os acessos</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select><button class="secondary-button" :disabled="loading" @click="load"><RefreshCw :size="15" :class="{spin:loading}"/>Atualizar</button></div>
  <p v-if="loading" class="users-loading" role="status"><LoaderCircle :size="19" class="spin"/>Carregando usuários…</p><p v-else-if="error" class="form-error" role="alert"><AlertCircle :size="17"/>{{error}}</p><div v-else-if="!rows.length" class="empty-state bordered"><UsersRound :size="30"/><h3>Nenhum usuário encontrado</h3><p>Tente outra busca ou cadastre um novo acesso.</p></div>
  <div v-else class="users-table-wrap"><table><thead><tr><th>Usuário</th><th>Forma de acesso</th><th>Perfil</th><th>Situação</th><th>Último acesso</th><th>Ações</th></tr></thead><tbody><tr v-for="user in rows" :key="user.id"><td><strong>{{user.name}}</strong><small>{{user.email}}</small><span v-if="user.id===currentUser.id" class="users-you">Você</span></td><td><span class="users-provider"><Building2 v-if="user.auth_provider==='suite'" :size="14"/><KeyRound v-else :size="14"/>{{user.auth_provider==='suite'?'Suíte Inovadora':'E-mail e senha'}}</span><small v-if="user.must_change_password">Troca de senha no próximo acesso</small></td><td>{{role(user.role)}}</td><td><span class="users-status" :class="{active:user.active}">{{user.active?'Ativo':'Inativo'}}</span></td><td>{{date(user.last_login_at)}}</td><td><button v-if="user.role!=='owner'||currentUser.role==='owner'" class="secondary-button" :aria-label="'Gerenciar acesso de '+user.name" @click="open(user)"><Pencil :size="14"/>Gerenciar</button><small v-else>Protegido pelo administrador principal</small></td></tr></tbody></table></div>
  <div v-if="!loading" class="catalog-pagination"><span>{{total}} usuário(s) · Página {{page}} de {{lastPage}}</span><button class="secondary-button" :disabled="page<=1" @click="changePage(page-1)"><ChevronLeft :size="14"/>Anterior</button><button class="secondary-button" :disabled="page>=lastPage" @click="changePage(page+1)">Próxima<ChevronRight :size="14"/></button></div>
  <div v-if="dialogOpen" class="modal-backdrop" @click.self="close"><section ref="dialog" class="modal users-access-dialog" role="dialog" aria-modal="true" aria-label="Gerenciar acesso"><button class="modal-close icon-button" aria-label="Fechar cadastro de usuário" :disabled="saving" @click="close"><X :size="19"/></button><span class="modal-icon"><UsersRound :size="25"/></span><h2>{{selected?'Gerenciar acesso':'Cadastrar usuário'}}</h2><p class="modal-description">{{suiteAccount?'A identidade e a senha deste colaborador são gerenciadas pela Suíte. Seu perfil é de administrador.':'Disponibilize um acesso pessoal ao G-Analise IA.'}}</p><form @submit.prevent="save"><label>Nome<input v-model="form.name" autocomplete="off" required maxlength="200" :disabled="saving||suiteAccount"></label><label>E-mail<input v-model="form.email" type="email" autocomplete="off" required maxlength="254" :disabled="saving||suiteAccount"></label><label>Perfil<select v-model="form.role" :disabled="saving||suiteAccount||ownAccount"><option v-if="form.role==='owner'" value="owner">Administrador principal</option><option value="admin">Administrador — gerencia usuários e recursos</option><option value="editor">Autor — cria e mantém seus projetos</option><option value="viewer">Leitura — consulta dados e prévias</option></select></label><label v-if="selected" class="users-checkbox"><input v-model="form.active" type="checkbox" :disabled="saving||ownAccount">Acesso ativo ao G-Analise IA</label><p v-if="selected&&!ownAccount" class="users-access-help">Inativar encerra as sessões locais e cancela tarefas pendentes. Os projetos são preservados. Operações já recebidas pelo BI podem concluir.</p><label v-if="selected&&!suiteAccount&&!ownAccount" class="users-checkbox"><input v-model="resetPassword" type="checkbox" :disabled="saving">Definir uma nova senha inicial</label><template v-if="!selected||resetPassword"><label>Senha inicial<input v-model="form.password" type="password" required minlength="12" maxlength="64" autocomplete="new-password" :disabled="saving"></label><label>Confirme a senha inicial<input v-model="form.password_confirmation" type="password" required minlength="12" maxlength="64" autocomplete="new-password" :disabled="saving"></label><p class="users-access-help">Use pelo menos 12 caracteres, com maiúsculas, minúsculas e números. A pessoa deverá trocar esta senha no primeiro acesso. Entregue-a por um canal privado.</p></template><p v-if="ownAccount" class="users-access-help">Para trocar sua senha, use Segurança da conta no menu lateral.</p><p v-if="formError" class="form-error" role="alert"><AlertCircle :size="16"/>{{formError}}</p><div class="modal-footer"><button type="button" class="secondary-button" :disabled="saving" @click="close">Cancelar</button><button class="primary-button" :disabled="saving"><LoaderCircle v-if="saving" :size="16" class="spin"/>{{selected?'Salvar acesso':'Cadastrar usuário'}}</button></div></form></section></div>
 </div>
</template>
<style scoped>
.users-management{max-width:1420px;width:100%;margin:0 auto}.users-suite-note{display:flex;align-items:flex-start;gap:13px;padding:20px;background:#f0f6ff;border:1px solid #dce8f9;border-radius:11px;color:#577fab;margin-bottom:24px}.users-suite-note strong{font-size:13px;color:#3e628f}.users-suite-note p{font-size:12px;line-height:1.8;margin-top:7px;color:#748ba8}.users-toolbar{display:flex;align-items:center;gap:12px;margin-bottom:22px}.users-toolbar .input-with-icon{flex:1;max-width:440px;width:auto;background:#fff}.users-toolbar select{font-size:12px;padding:10px;border:1px solid #e0e6f0;border-radius:7px;color:#6c809c;background:#fff}.users-loading{display:flex;align-items:center;gap:10px;padding:40px 0;font-size:13px;color:#6c83a2}.users-table-wrap{overflow:auto;border:1px solid #e1e7ef;border-radius:10px;background:#fff}.users-table-wrap table{border-collapse:collapse;width:100%;text-align:left;font-size:12px;min-width:860px}.users-table-wrap th{background:#f7f9fd;font-weight:600;font-size:11px;color:#788ca7;padding:15px}.users-table-wrap td{padding:17px 15px;border-top:1px solid #eaf0f6;color:#617a9b;vertical-align:middle}.users-table-wrap td strong{display:block;color:#3f5777;font-size:13px;font-weight:600}.users-table-wrap td small{display:block;color:#8b9bb1;font-size:10px;line-height:1.7;margin-top:5px}.users-provider{display:flex;align-items:center;gap:7px;white-space:nowrap}.users-status{display:inline-block;font-size:10px;padding:5px 8px;border-radius:5px;background:#f1f3f7;color:#8793a5}.users-status.active{background:#edf8f1;color:#448463}.users-you{display:inline-block;font-size:9px;color:#5f8dca;background:#f0f5fc;border-radius:3px;padding:3px 6px;margin-top:6px}.users-table-wrap .secondary-button{font-size:10px;padding:8px 10px}.users-access-dialog{max-width:560px}.users-checkbox{display:flex;align-items:center;gap:9px!important;font-size:12px}.users-checkbox input{width:15px;margin:0}.users-access-help{font-size:11px;line-height:1.8;color:#8291a8;margin:10px 0 18px}@media(max-width:760px){.users-toolbar{flex-wrap:wrap}.users-toolbar .input-with-icon{min-width:100%;max-width:none}.users-suite-note{padding:16px}.users-management .page-heading{align-items:flex-start}.users-management .page-heading>button{white-space:nowrap}}
</style>
